package com.rohit.inventory.controller; import com.rohit.inventory.dto.response.ApiResponse; import com.rohit.inventory.repository.AlertRepository; import java.time.Instant; import java.util.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/alerts") public class AlertActionController { private final AlertRepository alerts; public AlertActionController(AlertRepository alerts){this.alerts=alerts;} @PostMapping("/{id}/acknowledge") @PreAuthorize("hasAuthority('ALERT_ACKNOWLEDGE') or hasAuthority('INVENTORY_ADJUST')") public ApiResponse<Void> acknowledge(@PathVariable UUID id){var a=alerts.findById(id).orElseThrow();a.setStatus("ACKNOWLEDGED");return ApiResponse.success("Alert acknowledged",null);} @PostMapping("/{id}/resolve") @PreAuthorize("hasAuthority('ALERT_RESOLVE') or hasAuthority('INVENTORY_ADJUST')") public ApiResponse<Void> resolve(@PathVariable UUID id){var a=alerts.findById(id).orElseThrow();a.setStatus("RESOLVED");a.setResolvedAt(Instant.now());return ApiResponse.success("Alert resolved",null);} }
